import { z } from "zod";

import { FULLY_TRANSLATED_QUERY_KEY } from "@shared/application/dto/constants/translation-completeness-query.dto.constants";
import { LIMIT_QUERY_KEY } from "@shared/application/dto/constants/limit-query.dto.constants";
import { SORT_BY_QUERY_KEY, SORT_ORDER_QUERY_KEY } from "@shared/application/dto/constants/sort-query.dto.constants";
import { zIsFullyTranslated } from "@shared/application/dto/zod/validators/translation-completeness/translation-completeness.zod.validators";
import { zLimit } from "@shared/application/dto/zod/validators/limit/limit.zod.validators";
import { zSortOrder } from "@shared/application/dto/zod/validators/sort/sort.zod.validators";

import { ADMIN_QUESTION_SORTABLE_FIELDS } from "@question/domain/constants/question.constants";
import { QUESTION_AUTHOR_ROLE_QUERY_KEY, QUESTION_CATEGORY_QUERY_KEY, QUESTION_COGNITIVE_DIFFICULTY_QUERY_KEY, QUESTION_IDS_QUERY_KEY, QUESTION_IS_ADULT_CONTENT_QUERY_KEY, QUESTION_STATUS_QUERY_KEY, QUESTION_THEME_IDS_QUERY_KEY } from "@question/application/dto/shared/constants/question-filter-query.dto.constants";
import { QUESTION_SORT_BY_DEFAULT, QUESTION_SORT_BY_DESCRIPTION } from "@question/application/dto/shared/constants/question-sort.dto.constants";
import { zQuestionAuthorRole, zQuestionCategory, zQuestionCognitiveDifficulty, zQuestionIdsFilter, zQuestionIsAdultContentFilter, zQuestionStatus, zQuestionThemeIdsFilter } from "@question/application/dto/zod/validators/question.dto.zod.validators";

/**
 * Validates an admin question-list query: sorting, limiting and every supported filter, with the sort-field, sort-order and limit defaults applied.
 */
const ADMIN_FIND_QUESTIONS_QUERY_DTO = z.object({
  [SORT_BY_QUERY_KEY]: z.enum(ADMIN_QUESTION_SORTABLE_FIELDS)
    .optional()
    .default(QUESTION_SORT_BY_DEFAULT)
    .describe(QUESTION_SORT_BY_DESCRIPTION)
    .meta({ example: QUESTION_SORT_BY_DEFAULT }),
  [SORT_ORDER_QUERY_KEY]: zSortOrder(),
  [LIMIT_QUERY_KEY]: zLimit(),
  [QUESTION_STATUS_QUERY_KEY]: zQuestionStatus().optional(),
  [QUESTION_CATEGORY_QUERY_KEY]: zQuestionCategory().optional(),
  [QUESTION_COGNITIVE_DIFFICULTY_QUERY_KEY]: zQuestionCognitiveDifficulty().optional(),
  [QUESTION_AUTHOR_ROLE_QUERY_KEY]: zQuestionAuthorRole().optional(),
  [QUESTION_THEME_IDS_QUERY_KEY]: zQuestionThemeIdsFilter(),
  [QUESTION_IDS_QUERY_KEY]: zQuestionIdsFilter(),
  [QUESTION_IS_ADULT_CONTENT_QUERY_KEY]: zQuestionIsAdultContentFilter(),
  [FULLY_TRANSLATED_QUERY_KEY]: zIsFullyTranslated(),
});

/**
 * The parsed admin question-list query consumers receive, with the sort defaults resolved and omitted filters absent.
 */
type AdminFindQuestionsQueryDto = z.infer<typeof ADMIN_FIND_QUESTIONS_QUERY_DTO>;

export type { AdminFindQuestionsQueryDto };

export { ADMIN_FIND_QUESTIONS_QUERY_DTO };

import { z } from "zod";

import {
  zQuestionLocalizedStatement,
  zQuestionLocalizedAnswer,
  zQuestionLocalizedContext,
  zQuestionLocalizedTrivia,
} from "@question/application/dto/zod/validators/question-content/question-content.dto.zod.validators";

/**
 * Validates a question's admin content as localized maps, so an editor reads every translation of each field.
 */
const ADMIN_QUESTION_CONTENT_DTO = z.strictObject({
  statement: zQuestionLocalizedStatement(),
  answer: zQuestionLocalizedAnswer(),
  context: zQuestionLocalizedContext()
    .optional(),
  trivia: zQuestionLocalizedTrivia()
    .optional(),
}).describe("Question's content");

/**
 * The admin content consumers receive: statement, answer, context and trivia kept as localized maps.
 */
export type AdminQuestionContentDto = z.infer<typeof ADMIN_QUESTION_CONTENT_DTO>;

export { ADMIN_QUESTION_CONTENT_DTO };

import { z } from "zod";

import {
  zQuestionThemeAssignmentIsPrimary,
  zQuestionThemeAssignmentIsHint,
} from "@question/application/dto/zod/validators/question-theme-assignment/question-theme-assignment.dto.zod.validators";

import { ADMIN_QUESTION_THEME_DTO } from "@question-theme/contracts/dto/admin-question-theme/admin-question-theme.dto.shape";

/**
 * Validates one admin theme assignment: a localized theme plus its primary and hint flags.
 */
const ADMIN_QUESTION_THEME_ASSIGNMENT_DTO = z.strictObject({
  theme: ADMIN_QUESTION_THEME_DTO
    .describe("Question assigned theme"),
  isPrimary: zQuestionThemeAssignmentIsPrimary(),
  isHint: zQuestionThemeAssignmentIsHint(),
}).describe("Question's theme assignment");

/**
 * The admin theme assignment consumers receive, with the nested theme left as localized maps.
 */
export type AdminQuestionThemeAssignmentDto = z.infer<typeof ADMIN_QUESTION_THEME_ASSIGNMENT_DTO>;

export { ADMIN_QUESTION_THEME_ASSIGNMENT_DTO };

import { z } from "zod";

import { QUESTION_THEME_ASSIGNMENTS_MAX_ITEMS, QUESTION_THEME_ASSIGNMENTS_MIN_ITEMS } from "@question/domain/constants/question.constants";
import { ADMIN_QUESTION_THEME_ASSIGNMENT_DTO } from "@question/application/dto/admin-question/admin-question-theme-assignment/admin-question-theme-assignment.dto.shape";
import { zQuestionApplicableLocales, zQuestionCategory, zQuestionCognitiveDifficulty, zQuestionCreatedAt, zQuestionId, zQuestionIsAdultContent, zQuestionSourceUrls, zQuestionStatus, zQuestionUpdatedAt } from "@question/application/dto/zod/validators/question.dto.zod.validators";
import { QUESTION_REJECTION_DTO } from "@question/application/dto/shared/question-rejection/question-rejection.dto.shape";
import { QUESTION_AUTHOR_DTO } from "@question/application/dto/shared/question-author/question-author.dto.shape";
import { ADMIN_QUESTION_CONTENT_DTO } from "@question/application/dto/admin-question/admin-question-content/admin-question-content.dto.shape";

/**
 * Validates a complete admin question: localized content and themes, author, status, timestamps and an optional rejection.
 */
const ADMIN_QUESTION_DTO = z.strictObject({
  id: zQuestionId(),
  category: zQuestionCategory(),
  themes: z.array(ADMIN_QUESTION_THEME_ASSIGNMENT_DTO)
    .min(QUESTION_THEME_ASSIGNMENTS_MIN_ITEMS)
    .max(QUESTION_THEME_ASSIGNMENTS_MAX_ITEMS)
    .describe("Question's themes"),
  content: ADMIN_QUESTION_CONTENT_DTO,
  cognitiveDifficulty: zQuestionCognitiveDifficulty(),
  isAdultContent: zQuestionIsAdultContent(),
  author: QUESTION_AUTHOR_DTO,
  status: zQuestionStatus(),
  rejection: QUESTION_REJECTION_DTO
    .optional()
    .describe("Question's rejection details, if applicable"),
  sourceUrls: zQuestionSourceUrls(),
  applicableLocales: zQuestionApplicableLocales(0)
    .describe("Subset of locales this question is relevant for, if restricted"),
  createdAt: zQuestionCreatedAt(),
  updatedAt: zQuestionUpdatedAt(),
});

/**
 * The admin question consumers receive: every translation and the applicable-locale restriction exposed for editing.
 */
export type AdminQuestionDto = z.infer<typeof ADMIN_QUESTION_DTO>;

export { ADMIN_QUESTION_DTO };

