import type { FindRandomQuestionsBodyDto } from "@question/application/dto/find-random-questions-body/find-random-questions-body.dto.shape";
import type { Locale } from "@shared/domain/value-objects/locale/locale.types";
import type { FindRandomQuestionsOptions } from "@question/domain/types/question.types";

/**
 * Maps a random-question body DTO to the repository options, adding the resolved `locale` used to filter translations.
 */
function createFindRandomQuestionsOptionsFromBodyDto(bodyDto: FindRandomQuestionsBodyDto, locale: Locale): FindRandomQuestionsOptions {
  return {
    limit: bodyDto.limit,
    excludedIds: bodyDto.excludedIds,
    categories: bodyDto.categories,
    cognitiveDifficulties: bodyDto.cognitiveDifficulties,
    themeIds: bodyDto.themeIds,
    isAdultContent: bodyDto.isAdultContent,
    locale,
  };
}

export { createFindRandomQuestionsOptionsFromBodyDto };

import { pickDefinedValues } from "@shared/domain/rules/object/object.rules";
import { FULLY_TRANSLATED_QUERY_KEY } from "@shared/application/dto/constants/translation-completeness-query.dto.constants";

import { QUESTION_AUTHOR_ROLE_QUERY_KEY, QUESTION_CATEGORY_QUERY_KEY, QUESTION_COGNITIVE_DIFFICULTY_QUERY_KEY, QUESTION_IDS_QUERY_KEY, QUESTION_IS_ADULT_CONTENT_QUERY_KEY, QUESTION_STATUS_QUERY_KEY, QUESTION_THEME_IDS_QUERY_KEY } from "@question/application/dto/shared/constants/question-filter-query.dto.constants";

import type { AdminFindQuestionsQueryDto } from "@question/application/dto/admin-find-questions-query/admin-find-questions-query.dto.shape";
import type { FindQuestionsQueryDto } from "@question/application/dto/find-questions-query/find-questions-query.dto.shape";
import type { Locale } from "@shared/domain/value-objects/locale/locale.types";
import type { PublicQuestionFilterOptions, QuestionFilterOptions } from "@question/domain/types/question.types";

/**
 * Maps an admin question-list query DTO to the full repository filter options, dropping filters the client did not send.
 *
 * Returns `undefined` when no filter remains, which the repository reads as "match every question".
 */
function createQuestionFilterOptionsFromQueryDto(dto: AdminFindQuestionsQueryDto): Partial<QuestionFilterOptions> | undefined {
  return pickDefinedValues({
    status: dto[QUESTION_STATUS_QUERY_KEY],
    category: dto[QUESTION_CATEGORY_QUERY_KEY],
    cognitiveDifficulty: dto[QUESTION_COGNITIVE_DIFFICULTY_QUERY_KEY],
    authorRole: dto[QUESTION_AUTHOR_ROLE_QUERY_KEY],
    themeIds: dto[QUESTION_THEME_IDS_QUERY_KEY],
    ids: dto[QUESTION_IDS_QUERY_KEY],
    isAdultContent: dto[QUESTION_IS_ADULT_CONTENT_QUERY_KEY],
    isFullyTranslated: dto[FULLY_TRANSLATED_QUERY_KEY],
  });
}

/**
 * Maps a public question-list query DTO to the public filter options, adding the resolved `locale` used to keep only localized questions.
 */
function createPublicQuestionFilterOptionsFromQueryDto(dto: FindQuestionsQueryDto, locale: Locale): Partial<PublicQuestionFilterOptions> | undefined {
  return pickDefinedValues({
    category: dto[QUESTION_CATEGORY_QUERY_KEY],
    cognitiveDifficulty: dto[QUESTION_COGNITIVE_DIFFICULTY_QUERY_KEY],
    authorRole: dto[QUESTION_AUTHOR_ROLE_QUERY_KEY],
    themeIds: dto[QUESTION_THEME_IDS_QUERY_KEY],
    ids: dto[QUESTION_IDS_QUERY_KEY],
    isAdultContent: dto[QUESTION_IS_ADULT_CONTENT_QUERY_KEY],
    locale,
  });
}

export { createQuestionFilterOptionsFromQueryDto, createPublicQuestionFilterOptionsFromQueryDto };

import { createStatsZeroFilledRecord } from "@shared/application/helpers/stats/stats.helpers";

import {
  QUESTION_AUTHOR_ROLES,
  QUESTION_CATEGORIES,
  QUESTION_COGNITIVE_DIFFICULTIES,
  QUESTION_REJECTION_TYPES,
  QUESTION_STATUSES,
} from "@question/domain/constants/question.constants";

import type { QuestionStatsDto } from "@question/application/dto/question-stats/question-stats.dto.shape";
import type { QuestionStats } from "@question/domain/types/question.types";

/**
 * Maps domain question stats to the HTTP stats DTO, zero-filling every status, category, difficulty, author role and rejection type so the response shape stays stable.
 */
function createQuestionStatsDtoFromStats(stats: QuestionStats): QuestionStatsDto {
  return {
    total: stats.total,
    byStatus: createStatsZeroFilledRecord(QUESTION_STATUSES, stats.byStatus),
    byCategory: createStatsZeroFilledRecord(QUESTION_CATEGORIES, stats.byCategory),
    byCognitiveDifficulty: createStatsZeroFilledRecord(QUESTION_COGNITIVE_DIFFICULTIES, stats.byCognitiveDifficulty),
    byAuthorRole: createStatsZeroFilledRecord(QUESTION_AUTHOR_ROLES, stats.byAuthorRole),
    byRejectionType: createStatsZeroFilledRecord(QUESTION_REJECTION_TYPES, stats.byRejectionType),
    byTranslationCompleteness: stats.byTranslationCompleteness,
  };
}

export { createQuestionStatsDtoFromStats };

import type { QuestionThemeAssignmentCreationDto } from "@question/application/dto/question-creation/question-theme-assignment-creation/question-theme-assignment-creation.dto.shape";
import type { QuestionThemeAssignmentModificationDto } from "@question/application/dto/question-theme-assignment-modification/question-theme-assignment-modification.dto.shape";
import type { QuestionThemeAssignmentCreationCommand, QuestionThemeAssignmentModificationCommand } from "@question/application/commands/question.commands";
import type { QuestionThemeAssignmentCreationContract } from "@question/domain/repositories/question.repository-contracts.types";

/**
 * Maps a theme-assignment creation DTO to the repository contract, keeping only the fields the repository persists.
 */
function createQuestionThemeAssignmentCreationContractFromDto(questionThemeAssignmentDto: QuestionThemeAssignmentCreationDto): QuestionThemeAssignmentCreationContract {
  return {
    themeId: questionThemeAssignmentDto.themeId,
    isPrimary: questionThemeAssignmentDto.isPrimary,
    isHint: questionThemeAssignmentDto.isHint,
  };
}

/**
 * Wraps a theme-assignment creation DTO and its target question id into a creation command.
 */
function createQuestionThemeAssignmentCreationCommandFromDto(questionId: string, dto: QuestionThemeAssignmentCreationDto): QuestionThemeAssignmentCreationCommand {
  return {
    questionId,
    payload: createQuestionThemeAssignmentCreationContractFromDto(dto),
  };
}

/**
 * Builds a theme-assignment modification command from the question id, the theme id and the modification DTO.
 */
function createQuestionThemeAssignmentModificationCommandFromDto(
  questionId: string,
  themeId: string,
  dto: QuestionThemeAssignmentModificationDto,
): QuestionThemeAssignmentModificationCommand {
  return {
    questionId,
    themeId,
    payload: {
      isPrimary: dto.isPrimary,
      isHint: dto.isHint,
    },
  };
}

export {
  createQuestionThemeAssignmentCreationContractFromDto,
  createQuestionThemeAssignmentCreationCommandFromDto,
  createQuestionThemeAssignmentModificationCommandFromDto,
};

import { createTranslationFromLocalizedText, createTranslationsFromLocalizedTexts } from "@shared/application/mappers/localization/localization.mappers";

import { computeQuestionStatusFromAuthorRole } from "@question/domain/rules/question.rules";
import { createQuestionThemeAssignmentCreationContractFromDto } from "@question/application/mappers/question-theme-assignment/question-theme-assignment.mappers";

import { createAdminQuestionThemeDtoFromEntity, createQuestionThemeDtoFromEntity } from "@question-theme/contracts/dto/question-theme.dto.mappers";

import type { AdminQuestionThemeAssignmentDto } from "@question/application/dto/admin-question/admin-question-theme-assignment/admin-question-theme-assignment.dto.shape";
import type { AdminQuestionDto } from "@question/application/dto/admin-question/admin-question.dto.shape";
import type { QuestionThemeAssignmentDto } from "@question/application/dto/question/question-theme-assignment/question-theme-assignment.dto.shape";
import type { QuestionContentDto } from "@question/application/dto/question/question-content/question-content.dto.shape";
import type { QuestionDto } from "@question/application/dto/question/question.dto.shape";
import type { QuestionAuthorCreationDto } from "@question/application/dto/question-creation/question-author-creation/question-author-creation.dto.shape";
import type { QuestionContentCreationDto } from "@question/application/dto/question-creation/question-content-creation/question-content-creation.dto.shape";
import type { QuestionCreationDto } from "@question/application/dto/question-creation/question-creation.dto.shape";
import type { QuestionModificationDto } from "@question/application/dto/question-modification/question-modification.dto.shape";
import type { QuestionContent, QuestionThemeAssignment } from "@question/domain/types/question.value-objects";
import type { Question } from "@question/domain/types/question.entities";
import type { QuestionCreationCommand, QuestionModificationCommand } from "@question/application/commands/question.commands";
import type { QuestionAuthorCreationContract, QuestionContentCreationContract } from "@question/domain/repositories/question.repository-contracts.types";
import type { LocalizationOptions } from "@shared/domain/value-objects/locale/locale.types";

/**
 * Maps question content to its public DTO, resolving every localized field for the requested locale.
 *
 * Absent `context` and `trivia` stay `undefined` rather than being replaced by a placeholder.
 */
function createQuestionContentDtoFromEntity(questionContent: QuestionContent, localizationOptions: LocalizationOptions): QuestionContentDto {
  const context = questionContent.context ? createTranslationFromLocalizedText(questionContent.context, localizationOptions) : undefined;
  const trivia = questionContent.trivia ? createTranslationsFromLocalizedTexts(questionContent.trivia, localizationOptions) : undefined;

  return {
    statement: createTranslationFromLocalizedText(questionContent.statement, localizationOptions),
    answer: createTranslationFromLocalizedText(questionContent.answer, localizationOptions),
    context,
    trivia,
  };
}

/**
 * Maps one theme assignment to its public DTO, resolving the nested theme for the requested locale.
 */
function createQuestionThemeAssignmentDtoFromEntity(questionThemeAssignment: QuestionThemeAssignment, localizationOptions: LocalizationOptions): QuestionThemeAssignmentDto {
  return {
    theme: createQuestionThemeDtoFromEntity(questionThemeAssignment.theme, localizationOptions),
    isPrimary: questionThemeAssignment.isPrimary,
    isHint: questionThemeAssignment.isHint,
  };
}

/**
 * Maps a question entity to the public question DTO, localizing content and themes and converting the timestamps to ISO strings.
 *
 * `sourceUrls` is copied into a new array so the response does not alias the domain `Set`.
 */
function createQuestionDtoFromEntity(question: Question, localizationOptions: LocalizationOptions): QuestionDto {
  return {
    id: question.id,
    themes: question.themes.map(themeAssignment => createQuestionThemeAssignmentDtoFromEntity(themeAssignment, localizationOptions)),
    content: createQuestionContentDtoFromEntity(question.content, localizationOptions),
    category: question.category,
    cognitiveDifficulty: question.cognitiveDifficulty,
    isAdultContent: question.isAdultContent,
    author: question.author,
    status: question.status,
    rejection: question.rejection,
    sourceUrls: [...question.sourceUrls],
    createdAt: question.createdAt.toISOString(),
    updatedAt: question.updatedAt.toISOString(),
  };
}

/**
 * Maps one theme assignment to its admin DTO, keeping the nested theme in its localized-map form.
 */
function createAdminQuestionThemeAssignmentDtoFromEntity(questionThemeAssignment: QuestionThemeAssignment): AdminQuestionThemeAssignmentDto {
  return {
    theme: createAdminQuestionThemeDtoFromEntity(questionThemeAssignment.theme),
    isPrimary: questionThemeAssignment.isPrimary,
    isHint: questionThemeAssignment.isHint,
  };
}

/**
 * Maps a question entity to the admin DTO, exposing every localized map and the applicable locales, with timestamps as ISO strings.
 *
 * `sourceUrls` is copied into a new array so the response does not alias the domain `Set`.
 */
function createAdminQuestionDtoFromEntity(question: Question): AdminQuestionDto {
  return {
    id: question.id,
    themes: question.themes.map(themeAssignment => createAdminQuestionThemeAssignmentDtoFromEntity(themeAssignment)),
    content: question.content,
    category: question.category,
    cognitiveDifficulty: question.cognitiveDifficulty,
    isAdultContent: question.isAdultContent,
    author: question.author,
    rejection: question.rejection,
    sourceUrls: [...question.sourceUrls],
    applicableLocales: question.applicableLocales,
    status: question.status,
    createdAt: question.createdAt.toISOString(),
    updatedAt: question.updatedAt.toISOString(),
  };
}

/**
 * Maps a question-author creation DTO to the repository contract, keeping only the fields the repository persists.
 */
function createQuestionAuthorCreationContractFromDto(questionAuthorDto: QuestionAuthorCreationDto): QuestionAuthorCreationContract {
  return {
    role: questionAuthorDto.role,
    name: questionAuthorDto.name,
  };
}

/**
 * Maps a question-content creation DTO to the repository contract, preserving the localized maps as submitted.
 */
function createQuestionContentCreationContractFromDto(questionContentDto: QuestionContentCreationDto): QuestionContentCreationContract {
  return {
    statement: questionContentDto.statement,
    answer: questionContentDto.answer,
    context: questionContentDto.context,
    trivia: questionContentDto.trivia,
  };
}

/**
 * Maps a question-creation DTO to a creation command, deriving the initial status from the author role and copying the source URLs into a `Set`.
 */
function createQuestionCreationCommandFromDto(dto: QuestionCreationDto): QuestionCreationCommand {
  return {
    payload: {
      category: dto.category,
      themes: dto.themes.map(createQuestionThemeAssignmentCreationContractFromDto),
      content: createQuestionContentCreationContractFromDto(dto.content),
      cognitiveDifficulty: dto.cognitiveDifficulty,
      isAdultContent: dto.isAdultContent,
      author: createQuestionAuthorCreationContractFromDto(dto.author),
      status: computeQuestionStatusFromAuthorRole(dto.author.role),
      sourceUrls: new Set(dto.sourceUrls),
      applicableLocales: dto.applicableLocales,
    },
  };
}

/**
 * Maps a question-modification DTO and its target id to a modification command; omitted fields stay `undefined` so the repository leaves them untouched.
 */
function createQuestionModificationCommandFromDto(questionId: string, questionModificationDto: QuestionModificationDto): QuestionModificationCommand {
  return {
    questionId,
    payload: {
      category: questionModificationDto.category,
      cognitiveDifficulty: questionModificationDto.cognitiveDifficulty,
      isAdultContent: questionModificationDto.isAdultContent,
      sourceUrls: questionModificationDto.sourceUrls,
      content: questionModificationDto.content,
      applicableLocales: questionModificationDto.applicableLocales,
    },
  };
}

export {
  createQuestionContentDtoFromEntity,
  createQuestionThemeAssignmentDtoFromEntity,
  createQuestionDtoFromEntity,
  createAdminQuestionThemeAssignmentDtoFromEntity,
  createAdminQuestionDtoFromEntity,
  createQuestionAuthorCreationContractFromDto,
  createQuestionContentCreationContractFromDto,
  createQuestionCreationCommandFromDto,
  createQuestionModificationCommandFromDto,
};

