import { QuestionAlreadyArchivedError } from "@question/domain/errors/question-already-archived/question-already-archived.error";
import { QuestionNotFoundError } from "@question/domain/errors/question-not-found/question-not-found.error";
import { QUESTION_STATUS_ARCHIVED } from "@question/domain/constants/question.constants";

import type { Question } from "@question/domain/types/question.entities";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Soft-deletes a question by switching its status to archived.
 */
export class ArchiveQuestionUseCase {
  public constructor(private readonly questionRepository: QuestionRepository) {}

  /**
   * Returns the archived question.
   *
   * @throws `QuestionNotFoundError` when no question matches the id.
   * @throws `QuestionAlreadyArchivedError` when the question is already archived.
   */
  public async archive(id: string): Promise<Question> {
    await this.throwIfQuestionNotArchivable(id);
    const archivedQuestion = await this.questionRepository.archive(id);
    if (!archivedQuestion) {
      throw new QuestionNotFoundError(id);
    }
    return archivedQuestion;
  }

  private async throwIfQuestionNotArchivable(id: string): Promise<void> {
    const question = await this.questionRepository.findById(id);
    if (!question) {
      throw new QuestionNotFoundError(id);
    }
    if (question.status === QUESTION_STATUS_ARCHIVED) {
      throw new QuestionAlreadyArchivedError(id);
    }
  }
}

import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Counts the live questions attached to a theme, where live means pending or active.
 *
 * Published to the `question-theme` context: the theme archive rule uses this count, while theme stats count only active questions.
 */
class CountLiveQuestionsByThemeIdUseCase {
  public constructor(private readonly questionRepository: QuestionRepository) {}

  public async execute(themeId: string): Promise<number> {
    return this.questionRepository.countLiveByThemeId(themeId);
  }
}

export { CountLiveQuestionsByThemeIdUseCase };

import { QuestionCreationError } from "@question/domain/errors/question-creation/question-creation.error";
import { ReferencedQuestionThemeArchivedError } from "@question/domain/errors/referenced-question-theme-archived/referenced-question-theme-archived.error";

import { findArchivedQuestionTheme } from "@question-theme/domain/rules/question-theme.rules";
import { GetQuestionThemesByIdsOrThrowUseCase } from "@question-theme/application/use-cases/get-question-themes-by-ids-or-throw/get-question-themes-by-ids-or-throw.use-case";

import type { QuestionCreationCommand } from "@question/application/commands/question.commands";
import type { Question } from "@question/domain/types/question.entities";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Creates a question after checking that every referenced theme exists and that none is archived.
 */
export class CreateQuestionUseCase {
  public constructor(
    private readonly questionRepository: QuestionRepository,
    private readonly getQuestionThemesByIdsOrThrowUseCase: GetQuestionThemesByIdsOrThrowUseCase,
  ) {}

  /**
   * Returns the stored question after the write.
   *
   * @throws `QuestionThemeNotFoundError` when a referenced theme id matches no theme.
   * @throws `ReferencedQuestionThemeArchivedError` when one of the referenced themes is archived.
   * @throws `QuestionCreationError` when the question is written but cannot be read back.
   */
  public async create(questionCreateCommand: QuestionCreationCommand): Promise<Question> {
    await this.throwIfQuestionNotCreatable(questionCreateCommand);
    const question = await this.questionRepository.create(questionCreateCommand.payload);
    if (!question) {
      throw new QuestionCreationError();
    }
    return question;
  }

  private async throwIfQuestionNotCreatable(questionCreateCommand: QuestionCreationCommand): Promise<void> {
    const themeIds = new Set(questionCreateCommand.payload.themes.map(themeAssignment => themeAssignment.themeId));

    const questionThemes = await this.getQuestionThemesByIdsOrThrowUseCase.getByIdsOrThrow(themeIds);
    const archivedQuestionTheme = findArchivedQuestionTheme(questionThemes);
    if (archivedQuestionTheme) {
      throw new ReferencedQuestionThemeArchivedError(archivedQuestionTheme.id);
    }
  }
}

import { QuestionNotFoundError } from "@question/domain/errors/question-not-found/question-not-found.error";

import type { Question } from "@question/domain/types/question.entities";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Reads a single question and turns a missing question into a domain error.
 */
export class FindQuestionByIdUseCase {
  public constructor(private readonly questionRepository: QuestionRepository) {}

  /**
   * Returns the question matching the id.
   *
   * @throws `QuestionNotFoundError` when no question matches the id.
   */
  public async getById(id: string): Promise<Question> {
    const question = await this.questionRepository.findById(id);
    if (!question) {
      throw new QuestionNotFoundError(id);
    }
    return question;
  }
}

import type { Question } from "@question/domain/types/question.entities";
import type { FindAllOptions } from "@shared/domain/types/find/find.types";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";
import type { QuestionFilterOptions, QuestionSortableField } from "@question/domain/types/question.types";

/**
 * Lists questions for the admin and public routes using the given filter, sort and limit options.
 */
export class FindQuestionsUseCase {
  public constructor(private readonly questionRepository: QuestionRepository) {}

  public async list(options: FindAllOptions<QuestionSortableField, QuestionFilterOptions>): Promise<Question[]> {
    return this.questionRepository.findAll(options);
  }
}

import type { Question } from "@question/domain/types/question.entities";
import type { FindRandomQuestionsOptions } from "@question/domain/types/question.types";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Draws a random sample of active questions for a game round, honouring the exclusion and filter options.
 */
export class FindRandomQuestionsUseCase {
  public constructor(private readonly questionRepository: QuestionRepository) {}

  public async list(options: FindRandomQuestionsOptions): Promise<Question[]> {
    return this.questionRepository.findRandom(options);
  }
}

import { createQuestionStatsDtoFromStats } from "@question/application/mappers/question-stats/question-stats.mappers";

import type { QuestionStatsDto } from "@question/application/dto/question-stats/question-stats.dto.shape";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Aggregates the question counters and maps them to the stats response shape.
 */
export class GetQuestionStatsUseCase {
  public constructor(private readonly questionRepository: QuestionRepository) {}

  public async getStats(): Promise<QuestionStatsDto> {
    const stats = await this.questionRepository.getStats();

    return createQuestionStatsDtoFromStats(stats);
  }
}

import { QuestionNotFoundError } from "@question/domain/errors/question-not-found/question-not-found.error";

import type { QuestionModificationCommand } from "@question/application/commands/question.commands";
import type { Question } from "@question/domain/types/question.entities";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Applies a partial question modification and turns a missing question into a domain error.
 */
export class ModifyQuestionUseCase {
  public constructor(private readonly questionRepository: QuestionRepository) {}

  /**
   * Returns the question with the modification applied.
   *
   * @throws `QuestionNotFoundError` when no question matches the id.
   */
  public async modify(questionModificationCommand: QuestionModificationCommand): Promise<Question> {
    const { questionId, payload } = questionModificationCommand;
    const modifiedQuestion = await this.questionRepository.modify(questionId, payload);
    if (!modifiedQuestion) {
      throw new QuestionNotFoundError(questionId);
    }
    return modifiedQuestion;
  }
}

import { FindQuestionByIdUseCase } from "@question/application/use-cases/find-question-by-id/find-question-by-id.use-case";
import { QuestionThemeAssignmentAlreadyExistsError } from "@question/domain/errors/question-theme-assignment-already-exists/question-theme-assignment-already-exists.error";
import { QuestionThemeAssignmentCreationError } from "@question/domain/errors/question-theme-assignment-creation/question-theme-assignment-creation.error";
import { ensureQuestionThemeAssignmentsLimit, findQuestionThemeAssignmentInQuestionByThemeId } from "@question/domain/rules/question.rules";
import { ReferencedQuestionThemeArchivedError } from "@question/domain/errors/referenced-question-theme-archived/referenced-question-theme-archived.error";

import { FindQuestionThemeByIdUseCase } from "@question-theme/application/use-cases/find-question-theme-by-id/find-question-theme-by-id.use-case";
import { isQuestionThemeArchived } from "@question-theme/domain/rules/question-theme.rules";

import type { Question } from "@question/domain/types/question.entities";
import type { QuestionThemeAssignmentCreationCommand } from "@question/application/commands/question.commands";
import type { QuestionThemeAssignmentCreationContract } from "@question/domain/repositories/question.repository-contracts.types";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Assigns one theme to a question after checking that both exist, that the assignment is not a duplicate, that the question has room and that the theme is not archived.
 */
export class AssignThemeToQuestionUseCase {
  public constructor(
    private readonly questionRepository: QuestionRepository,
    private readonly findQuestionThemeByIdUseCase: FindQuestionThemeByIdUseCase,
    private readonly findQuestionByIdUseCase: FindQuestionByIdUseCase,
  ) {}

  /**
   * Returns the question with the new theme assignment.
   *
   * A conditional write that matches no document is re-evaluated against the stored question to surface the invariant that blocked it, falling back to the write error.
   *
   * @throws `QuestionNotFoundError` when no question matches the question id.
   * @throws `QuestionThemeNotFoundError` when no theme matches the assignment theme id.
   * @throws `QuestionThemeAssignmentAlreadyExistsError` when the theme is already assigned to the question.
   * @throws `QuestionMaximumThemesError` when the question already holds the maximum number of theme assignments.
   * @throws `ReferencedQuestionThemeArchivedError` when the theme is archived.
   * @throws `QuestionThemeAssignmentCreationError` when the question is written but cannot be read back.
   */
  public async assign(questionThemeAssignmentCreationCommand: QuestionThemeAssignmentCreationCommand): Promise<Question> {
    const { questionId, payload: questionThemeAssignmentPayload } = questionThemeAssignmentCreationCommand;
    await this.throwIfThemeNotAssignableToQuestion(questionThemeAssignmentPayload, questionId);
    const updatedQuestion = await this.questionRepository.assignTheme(questionId, questionThemeAssignmentPayload);
    if (!updatedQuestion) {
      return this.throwErrorForQuestionThemeAssignmentNoMatch(questionId, questionThemeAssignmentPayload);
    }
    return updatedQuestion;
  }

  private async throwErrorForQuestionThemeAssignmentNoMatch(questionId: string, questionThemeAssignmentContract: QuestionThemeAssignmentCreationContract): Promise<never> {
    await this.throwIfThemeNotAssignableToQuestion(questionThemeAssignmentContract, questionId);
    throw new QuestionThemeAssignmentCreationError(questionThemeAssignmentContract.themeId, questionId);
  }

  private async throwIfThemeNotAssignableToQuestion(questionThemeAssignmentContract: QuestionThemeAssignmentCreationContract, questionId: string): Promise<void> {
    const question = await this.findQuestionByIdUseCase.getById(questionId);
    const questionTheme = await this.findQuestionThemeByIdUseCase.getById(questionThemeAssignmentContract.themeId);

    const existingThemeAssignment = findQuestionThemeAssignmentInQuestionByThemeId(question, questionTheme.id);
    if (existingThemeAssignment) {
      throw new QuestionThemeAssignmentAlreadyExistsError(questionTheme.id, questionId);
    }
    ensureQuestionThemeAssignmentsLimit(question);
    if (isQuestionThemeArchived(questionTheme)) {
      throw new ReferencedQuestionThemeArchivedError(questionTheme.id);
    }
  }
}

import { FindQuestionByIdUseCase } from "@question/application/use-cases/find-question-by-id/find-question-by-id.use-case";
import { QuestionThemeAssignmentModificationError } from "@question/domain/errors/question-theme-assignment-modification/question-theme-assignment-modification.error";
import { ensureQuestionThemeAssignmentIsModifiable } from "@question/domain/rules/question.rules";

import type { QuestionThemeAssignmentModificationCommand } from "@question/application/commands/question.commands";
import type { Question } from "@question/domain/types/question.entities";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Modifies an existing theme assignment on a question, for example to promote it to primary or toggle its hint flag.
 */
export class ModifyQuestionThemeAssignmentUseCase {
  public constructor(
    private readonly questionRepository: QuestionRepository,
    private readonly findQuestionByIdUseCase: FindQuestionByIdUseCase,
  ) {}

  /**
   * Returns the question with the modified assignment.
   *
   * A conditional write that matches no document is re-evaluated against the stored question to surface the invariant that blocked it, falling back to the write error.
   *
   * @throws `QuestionNotFoundError` when no question matches the question id.
   * @throws `QuestionThemeAssignmentAbsentError` when the question has no assignment for the theme id.
   * @throws `QuestionThemeAssignmentModificationError` when the question is written but cannot be read back.
   */
  public async modify(command: QuestionThemeAssignmentModificationCommand): Promise<Question> {
    const { questionId, themeId, payload } = command;
    await this.throwIfThemeAssignmentNotModifiable(questionId, themeId);
    const updatedQuestion = await this.questionRepository.modifyThemeAssignment(questionId, themeId, payload);
    if (!updatedQuestion) {
      return this.throwErrorForQuestionThemeAssignmentModificationNoMatch(questionId, themeId);
    }
    return updatedQuestion;
  }

  private async throwErrorForQuestionThemeAssignmentModificationNoMatch(questionId: string, themeId: string): Promise<never> {
    await this.throwIfThemeAssignmentNotModifiable(questionId, themeId);
    throw new QuestionThemeAssignmentModificationError(themeId, questionId);
  }

  private async throwIfThemeAssignmentNotModifiable(questionId: string, themeId: string): Promise<void> {
    const question = await this.findQuestionByIdUseCase.getById(questionId);
    ensureQuestionThemeAssignmentIsModifiable(question, themeId);
  }
}

import { FindQuestionByIdUseCase } from "@question/application/use-cases/find-question-by-id/find-question-by-id.use-case";
import { QuestionThemeAssignmentRemovalError } from "@question/domain/errors/question-theme-assignment-removal/question-theme-assignment-removal.error";
import { QuestionMinimumThemesError } from "@question/domain/errors/question-minimum-themes/question-minimum-themes.error";
import { ensureQuestionThemeAssignmentIsRemovable } from "@question/domain/rules/question.rules";
import { QUESTION_THEME_ASSIGNMENTS_MIN_ITEMS } from "@question/domain/constants/question.constants";

import type { QuestionThemeAssignmentRemovalCommand } from "@question/application/commands/question.commands";
import type { Question } from "@question/domain/types/question.entities";
import type { QuestionRepository } from "@question/domain/repositories/question.repository.types";

/**
 * Removes a theme from a question after checking that the assignment exists, is not the primary one and that a theme remains.
 */
export class RemoveThemeFromQuestionUseCase {
  public constructor(
    private readonly questionRepository: QuestionRepository,
    private readonly findQuestionByIdUseCase: FindQuestionByIdUseCase,
  ) {}

  /**
   * Returns the question without the removed assignment.
   *
   * A conditional write that matches no document is re-evaluated floor-first, so a concurrent removal that lost the race reports the minimum-theme invariant that blocked it.
   *
   * @throws `QuestionNotFoundError` when no question matches the question id.
   * @throws `QuestionThemeAssignmentAbsentError` when the question has no assignment for the theme id.
   * @throws `QuestionPrimaryThemeAssignmentNotRemovableError` when the assignment is the primary one.
   * @throws `QuestionMinimumThemesError` when removing the assignment would leave the question below the minimum number of themes.
   * @throws `QuestionThemeAssignmentRemovalError` when the question is written but cannot be read back.
   */
  public async remove(questionAssignmentRemovalCommand: QuestionThemeAssignmentRemovalCommand): Promise<Question> {
    const { questionId, themeId } = questionAssignmentRemovalCommand;
    await this.throwIfThemeNotRemovableFromQuestion(questionId, themeId);
    const updatedQuestion = await this.questionRepository.removeTheme(questionId, themeId);
    if (!updatedQuestion) {
      return this.throwErrorForQuestionThemeRemovalNoMatch(questionId, themeId);
    }
    return updatedQuestion;
  }

  private async throwErrorForQuestionThemeRemovalNoMatch(questionId: string, themeId: string): Promise<never> {
    const question = await this.findQuestionByIdUseCase.getById(questionId);
    if (question.themes.length <= QUESTION_THEME_ASSIGNMENTS_MIN_ITEMS) {
      throw new QuestionMinimumThemesError(questionId);
    }
    ensureQuestionThemeAssignmentIsRemovable(question, themeId);
    throw new QuestionThemeAssignmentRemovalError(themeId, questionId);
  }

  private async throwIfThemeNotRemovableFromQuestion(questionId: string, themeId: string): Promise<void> {
    const question = await this.findQuestionByIdUseCase.getById(questionId);
    ensureQuestionThemeAssignmentIsRemovable(question, themeId);

    if (question.themes.length <= QUESTION_THEME_ASSIGNMENTS_MIN_ITEMS) {
      throw new QuestionMinimumThemesError(questionId);
    }
  }
}

