import { QUESTION_THEME_STATUS_ARCHIVED } from "@question-theme/domain/constants/question-theme.constants";

export class QuestionThemeAlreadyArchivedError extends Error {
  public constructor(questionThemeId: string) {
    super(`Question theme with id ${questionThemeId} already has status '${QUESTION_THEME_STATUS_ARCHIVED}'`);
    this.name = "QuestionThemeAlreadyArchivedError";
  }
}

export class QuestionThemeNotFoundError extends Error {
  public constructor(questionThemeId: string) {
    super(`Question theme with id ${questionThemeId} not found`);
    this.name = "QuestionThemeNotFoundError";
  }
}

export class QuestionThemeReferencedByLiveQuestionsError extends Error {
  public constructor(questionThemeId: string, liveQuestionCount: number) {
    super(`Question theme with id ${questionThemeId} is referenced by ${liveQuestionCount} live question(s) and cannot be archived`);
    this.name = "QuestionThemeReferencedByLiveQuestionsError";
  }
}

export class QuestionThemeSlugAlreadyExistsError extends Error {
  public constructor(slug: string) {
    super(`Question theme with slug ${slug} already exists`);
    this.name = "QuestionThemeSlugAlreadyExistsError";
  }
}

