import { createQuestionThemeFromPersistenceShape } from "@question-theme/contracts/persistence/question-theme.persistence.mappers";

import type { QuestionTheme } from "@question-theme/domain/types/question-theme.entities";
import type { QuestionThemeMongooseDocument, QuestionThemeMongooseSchemaShape } from "@question-theme/infrastructure/persistence/mongoose/types/question-theme.mongoose.types";

/**
 * Maps a Mongoose theme document or its raw schema shape to the domain entity through the published persistence mapper.
 *
 * A hydrated document is converted with `toObject()` first, so its localized nested paths reach the domain as plain objects instead of
 * Mongoose subdocuments carrying internal keys.
 */
function createQuestionThemeFromDocument(questionThemeDocument: QuestionThemeMongooseDocument | QuestionThemeMongooseSchemaShape): QuestionTheme {
  const questionThemePersistenceShape = "toObject" in questionThemeDocument ? questionThemeDocument.toObject() : questionThemeDocument;

  return createQuestionThemeFromPersistenceShape(questionThemePersistenceShape);
}

export {
  createQuestionThemeFromDocument,
};

import { pickDefinedValues } from "@shared/domain/rules/object/object.rules";
import { buildIsFullyTranslatedMatchCondition } from "@shared/infrastructure/persistence/mongoose/helpers/translation-completeness.mongoose.helpers";

import { QUESTION_THEME_TRANSLATION_COMPLETENESS_FIELD_SPECS } from "@question-theme/infrastructure/persistence/mongoose/constants/question-theme.mongoose.constants";

import type { AdminQuestionThemeFilterOptions } from "@question-theme/domain/types/question-theme.types";

/**
 * Builds the query filter for the admin theme list from the defined filters, returning an empty query when nothing is set.
 */
function buildQuestionThemeFilterQuery(filters?: Partial<AdminQuestionThemeFilterOptions>): Record<string, unknown> {
  if (!filters) {
    return {};
  }
  const baseConditions = pickDefinedValues({ status: filters.status }) ?? {};

  if (filters.isFullyTranslated === undefined) {
    return baseConditions;
  }
  return {
    ...baseConditions,
    ...buildIsFullyTranslatedMatchCondition(QUESTION_THEME_TRANSLATION_COMPLETENESS_FIELD_SPECS, filters.isFullyTranslated),
  };
}

export { buildQuestionThemeFilterQuery };

import { MONGO_DUPLICATE_KEY_ERROR_CODE } from "@shared/infrastructure/persistence/mongoose/constants/mongoose.constants";

import { QuestionThemeSlugAlreadyExistsError } from "@question-theme/domain/errors/question-theme-slug-already-exists/question-theme-slug-already-exists.error";

import type { MongoDuplicateKeyError } from "@question-theme/infrastructure/persistence/mongoose/repository/helpers/question-theme.mongoose.helpers.types";

/**
 * Narrows an unknown error to a Mongo duplicate-key error by checking its numeric code, so non-error values are rejected.
 */
function isMongoDuplicateKeyError(error: unknown): error is MongoDuplicateKeyError {
  if (!(error instanceof Object) || !("code" in error) || !Error.isError(error)) {
    return false;
  }
  return error.code === MONGO_DUPLICATE_KEY_ERROR_CODE;
}

/**
 * Translates a duplicate-key rejection on the unique slug index into the domain error and rethrows every other error unchanged.
 *
 * @throws `QuestionThemeSlugAlreadyExistsError` when `slug` is provided and Mongo reports a duplicate key.
 */
function throwIfDuplicateKeyError(error: unknown, slug?: string): never {
  if (slug !== undefined && isMongoDuplicateKeyError(error)) {
    throw new QuestionThemeSlugAlreadyExistsError(slug);
  }
  throw error;
}

export {
  isMongoDuplicateKeyError,
  throwIfDuplicateKeyError,
};

