import { SECONDS_TO_MILLISECONDS_FACTOR, THROTTLER_DEFAULT_TIER_NAME, THROTTLER_SUSTAINED_TIER_NAME } from "@src/infrastructure/api/server/throttler/constants/throttler.constants";

import type { ThrottlerModuleOptions, ThrottlerOptions } from "@nestjs/throttler";
import type { ThrottlerConfigFromEnv, ThrottlerTierConfigFromEnv } from "@src/infrastructure/api/config/types/config.types";

function createThrottlerOptions(name: string, tierConfig: ThrottlerTierConfigFromEnv): ThrottlerOptions {
  return {
    name,
    ttl: tierConfig.ttlSeconds * SECONDS_TO_MILLISECONDS_FACTOR,
    limit: tierConfig.limit,
  };
}

/**
 * Builds the `default` and `sustained` library tiers from the validated configuration, converting each window from seconds to the library's millisecond unit.
 *
 * No block duration is set, so every tier blocks for its own window length.
 */
function createThrottlerModuleOptions(throttlerConfig: ThrottlerConfigFromEnv): ThrottlerModuleOptions {
  return {
    throttlers: [
      createThrottlerOptions(THROTTLER_DEFAULT_TIER_NAME, throttlerConfig.default),
      createThrottlerOptions(THROTTLER_SUSTAINED_TIER_NAME, throttlerConfig.sustained),
    ],
  };
}

export { createThrottlerModuleOptions };

import { createHash } from "node:crypto";

import { HttpException, Injectable, Logger } from "@nestjs/common";
import { ThrottlerGuard } from "@nestjs/throttler";

import { MINIMUM_RETRY_AFTER_SECONDS, RETRY_AFTER_HEADER_NAME, TOO_MANY_REQUESTS_ERROR_BODY } from "@src/infrastructure/api/server/throttler/constants/throttler.constants";

import { getSecurityEventRoute, logRequestThrottledEvent } from "@shared/infrastructure/helpers/security-events/security-events.helpers";

import type { ExecutionContext } from "@nestjs/common";
import type { ThrottlerLimitDetail } from "@nestjs/throttler";

/**
 * Rate-limits every business route with the two configured API-wide, per-client budgets.
 *
 * The storage key hashes the tier name and the library-normalized tracker only, so all routes of a tier share one budget per
 * client. The library's per-tier retry headers are suppressed in favour of one plain `Retry-After` in seconds, and an
 * over-budget request emits `request.throttled` and is rejected with the shared 429 error envelope, which carries no client
 * identity or counter state.
 */
@Injectable()
export class ApiThrottlerGuard extends ThrottlerGuard {
  protected override logger = new Logger(ApiThrottlerGuard.name);

  // Acceptable as the override must stay an instance method to match the base class contract.
  // oxlint-disable-next-line eslint/class-methods-use-this
  protected override generateKey(_context: ExecutionContext, tracker: string, throttlerName: string): string {
    return createHash("sha256")
      .update(`${throttlerName}:${tracker}`)
      .digest("hex");
  }

  protected override setResponseHeader(response: Record<string, unknown>, name: string, value: string | number): void {
    if (name.startsWith(RETRY_AFTER_HEADER_NAME)) {
      return;
    }
    super.setResponseHeader(response, name, value);
  }

  // Acceptable as the override rejects instead of awaiting, while the base class declares a Promise return type.
  // oxlint-disable-next-line typescript/require-await
  protected override async throwThrottlingException(context: ExecutionContext, throttlerLimitDetail: ThrottlerLimitDetail): Promise<void> {
    const { req, res } = this.getRequestResponse(context);
    const retryAfterSeconds = Math.max(MINIMUM_RETRY_AFTER_SECONDS, throttlerLimitDetail.timeToBlockExpire);
    super.setResponseHeader(res, RETRY_AFTER_HEADER_NAME, retryAfterSeconds);
    logRequestThrottledEvent(this.logger, {
      route: getSecurityEventRoute(req),
      retryAfterSeconds,
    });

    throw new HttpException(TOO_MANY_REQUESTS_ERROR_BODY, TOO_MANY_REQUESTS_ERROR_BODY.statusCode);
  }
}

