import { z } from "zod";

import { API_RESPONSE_EXCEPTION_VALIDATION_DETAILS_DTO } from "@shared/application/dto/api-response-exception/api-response-exception-validation-details/api-response-exception-validation-details.dto.shape";

/**
 * Validates the API error response body: HTTP status, message, error label, optional validation details and an optional error code.
 */
const API_RESPONSE_EXCEPTION_DTO = z.strictObject({
  statusCode: z.number()
    .describe("HTTP status code of the error response")
    .meta({ example: 400 }),
  message: z.string()
    .describe("Error message")
    .meta({ example: "The request could not be understood by the server due to malformed syntax." }),
  error: z.string()
    .describe("Short description of the HTTP error")
    .meta({ example: "Bad Request" }),
  validationDetails: z.array(API_RESPONSE_EXCEPTION_VALIDATION_DETAILS_DTO)
    .optional()
    .describe("List of validation errors, when requested DTO validation fails"),
  errorCode: z.string()
    .optional()
    .describe("Machine-readable error code for frontend mapping and localization")
    .meta({ example: "question-theme-referenced-by-live-questions" }),
});

/**
 * The error body consumers receive; `validationDetails` appears only for request-validation failures, and `errorCode` appears
 * for mapped domain errors and for curated infrastructure HTTP errors such as the throttler's `too-many-requests`.
 */
export type ApiResponseExceptionDto = z.infer<typeof API_RESPONSE_EXCEPTION_DTO>;

export { API_RESPONSE_EXCEPTION_DTO };

