    it("should have the correct refinement message for uniqueness when duplicates are present.", () => {
      const schema = zQuestionCategoriesFilter();
      const notUniqueTestValue = ["trivia", "trivia"];
      const result = schema.safeParse(notUniqueTestValue);

      expect(result.error?.issues[0].message).toBe("Categories must be unique");
    });
  });

  describe(zQuestionCognitiveDifficultiesFilter, () => {
    it.each<{
      test: string;
      value: unknown;
      expected: boolean;
    }>([
      {
        test: "should return true when an array with a valid cognitive difficulty is provided.",
        value: ["easy"],
        expected: true,
      },
      {
        test: "should return true when an array with multiple valid cognitive difficulties is provided.",
        value: ["easy", "hard"],
        expected: true,
      },
      {
        test: "should return true when a single string cognitive difficulty is provided.",
        value: "easy",
        expected: true,
      },
      {
        test: "should return true when value is undefined.",
        value: undefined,
        expected: true,
      },
      {
        test: "should return false when an empty array is provided.",
        value: [],
        expected: false,
      },
      {
        test: "should return false when an array contains an invalid cognitive difficulty.",
        value: ["extreme"],
        expected: false,
      },
      {
        test: "should return false when an array contains duplicate cognitive difficulties.",
        value: ["easy", "easy"],
        expected: false,
      },
    ])("$test", ({ value, expected }) => {
      const result = zQuestionCognitiveDifficultiesFilter().safeParse(value);

      expect(result.success).toBe(expected);
    });

    it("should normalize a single string value to an array when parsed.", () => {
      const result = zQuestionCognitiveDifficultiesFilter().safeParse("easy");

      expect(result.data).toStrictEqual(["easy"]);
    });

    it("should have the correct description when called.", () => {
      const schema = zQuestionCognitiveDifficultiesFilter();

      expect(schema.description).toBe("List of cognitive difficulties to include (OR logic)");
    });

    it("should have the correct refinement message for uniqueness when duplicates are present.", () => {
      const schema = zQuestionCognitiveDifficultiesFilter();
      const notUniqueTestValue = ["easy", "easy"];
      const result = schema.safeParse(notUniqueTestValue);

      expect(result.error?.issues[0].message).toBe("Cognitive difficulties must be unique");
    });
  });

  describe(zQuestionApplicableLocales, () => {
    it.each<{
      test: string;
      value: unknown;
      minItems: number;
      expected: boolean;
    }>([
      {
        test: "should return true when a valid subset of locales is provided.",
        value: ["fr"],
        minItems: 1,
        expected: true,
      },
      {
        test: "should return true when all locales are provided.",
        value: ["en", "fr", "es", "de", "it", "pt"],
        minItems: 1,
        expected: true,
      },
      {
        test: "should return true when value is undefined.",
        value: undefined,
        minItems: 1,
        expected: true,
      },
      {
        test: "should return false when an empty array is provided with default minItems.",
        value: [],
        minItems: 1,
        expected: false,
      },
      {
        test: "should return true when an empty array is provided with minItems 0.",
        value: [],
        minItems: 0,
        expected: true,
      },
      {
        test: "should return false when duplicate locales are provided.",
        value: ["fr", "fr"],
        minItems: 1,
        expected: false,
      },
      {
        test: "should return false when an invalid locale is provided.",
        value: ["fr", "jp"],
        minItems: 1,
        expected: false,
      },
      {
        test: "should return false when more than the maximum number of locales is provided.",
        value: ["en", "fr", "es", "de", "it", "pt", "en"],
        minItems: 1,
        expected: false,
      },
    ])("$test", ({ value, minItems, expected }) => {
      const result = zQuestionApplicableLocales(minItems).safeParse(value);

      expect(result.success).toBe(expected);
    });

    it("should have the correct description when called.", () => {
      const schema = zQuestionApplicableLocales();

      expect(schema.description).toBe("Subset of locales this question is relevant for; omit if relevant for all locales");
    });

    it("should have the correct refinement message for uniqueness when duplicates are present.", () => {
      const schema = zQuestionApplicableLocales();
      const result = schema.safeParse(["fr", "fr"]);

      expect(result.error?.issues[0].message).toBe("Locales must be unique");
    });
  });

  describe(zQuestionIsAdultContent, () => {
    it.each<{
      test: string;
      value: unknown;
      expected: boolean;
    }>([
      {
        test: "should return true when a boolean true is provided.",
        value: true,
        expected: true,
      },
      {
        test: "should return true when a boolean false is provided.",
        value: false,
        expected: true,
      },
      {
        test: "should return false when a string is provided.",
        value: "true",
        expected: false,
      },
    ])("$test", ({ value, expected }) => {
      const result = zQuestionIsAdultContent().safeParse(value);

      expect(result.success).toBe(expected);
    });

    it("should have the correct description when called.", () => {
      const schema = zQuestionIsAdultContent();

      expect(schema.description).toBe("Whether the question contains adult content");
    });
  });

  describe(zQuestionIsAdultContentFilter, () => {
    it.each<{ input: string; expected: boolean }>([
      { input: "true", expected: true },
      { input: "TRUE", expected: true },
      { input: "false", expected: false },
      { input: "FALSE", expected: false },
    ])("should parse '$input' to $expected when the input is a valid boolean string.", ({ input, expected }) => {
      const isAdultContent = zQuestionIsAdultContentFilter().parse(input);

      expect(isAdultContent).toBe(expected);
    });

    it("should return undefined when input is undefined.", () => {
      const isAdultContent = zQuestionIsAdultContentFilter().parse(undefined);

      expect(isAdultContent).toBeUndefined();
    });

    it.each<unknown>(["maybe", "yes", "no", ""])("should throw a zod error when the input is '%s'.", input => {
      expect(() => zQuestionIsAdultContentFilter().parse(input)).toThrow(ZodError);
    });

    it("should have the correct description when called.", () => {
      const schema = zQuestionIsAdultContentFilter();

      expect(schema.description).toBe("Filters questions by adult content");
    });
  });

  describe(zQuestionIsAdultContentBooleanFilter, () => {
    it.each<{ input: boolean; expected: boolean }>([
      { input: true, expected: true },
      { input: false, expected: false },
    ])("should parse '$input' to $expected when the input is a valid boolean.", ({ input, expected }) => {
      const isAdultContent = zQuestionIsAdultContentBooleanFilter().parse(input);

      expect(isAdultContent).toBe(expected);
    });

    it("should return undefined when input is undefined.", () => {
      const isAdultContent = zQuestionIsAdultContentBooleanFilter().parse(undefined);

      expect(isAdultContent).toBeUndefined();
    });

    it.each<unknown>(["true", "false", 1, 0])("should throw a zod error when the input is '%s'.", input => {
      expect(() => zQuestionIsAdultContentBooleanFilter().parse(input)).toThrow(ZodError);
    });

    it("should have the correct description when called.", () => {
      const schema = zQuestionIsAdultContentBooleanFilter();

      expect(schema.description).toBe("Filters questions by adult content");
    });
  });
});

