      expect(() => ADMIN_QUESTION_DTO.parse(dtoWithEmptyThemes)).toThrow(ZodError);
    });

    it("should throw zod error when themes is invalid.", () => {
      const dtoWithInvalidThemes = { ...validAdminQuestionDto, themes: "invalid" };

