            createdAt: "2026-04-14T00:00:00.000Z",
          },
          isPrimary: true,
          isHint: false,
        },
      ],
      content: { statement: "What is the capital of France?", answer: "Paris" },
      cognitiveDifficulty: "easy",
      isAdultContent: false,
      author: { role: "admin", name: "TestAuthor" },
      status: "active",
