          },
          isPrimary: true,
          isHint: false,
        },
        {
          theme: {
            id: "60af924f4f1a2563f8e8b458",
            slug: "science",
            label: "Science",
            aliases: ["sci", "nature"],
            description: "Science questions",
            color: "#33FF57",
            status: "active",
            updatedAt: "2026-04-14T00:00:00.000Z",
            createdAt: "2026-04-14T00:00:00.000Z",
          },
          isPrimary: false,
          isHint: true,
        },
