    validQuestionThemeDto = {
      id: "60af924f4f1a2563f8e8b456",
      slug: "general-knowledge",
      label: "General Knowledge",
      aliases: ["gk", "general"],
      description: "A theme for general knowledge questions",
      color: "#FF5733",
