import { ZodError } from "zod";

import { SORT_ORDERS } from "@shared/domain/constants/sort/sort.constants";
import { LIMIT_DESCRIPTION, LIMIT_DEFAULT, LIMIT_MINIMUM } from "@shared/application/dto/zod/validators/limit/constants/limit.zod.validators.constants";

import { ADMIN_FIND_QUESTION_THEMES_QUERY_DTO } from "@question-theme/application/dto/admin-find-question-themes-query/admin-find-question-themes-query.dto.shape";
import { ADMIN_QUESTION_THEME_SORTABLE_FIELDS, QUESTION_THEME_STATUSES } from "@question-theme/domain/constants/question-theme.constants";
import { QUESTION_THEME_SORT_BY_DEFAULT, QUESTION_THEME_SORT_BY_DESCRIPTION, QUESTION_THEME_SORT_ORDER_DEFAULT, QUESTION_THEME_SORT_ORDER_DESCRIPTION } from "@question-theme/application/dto/shared/constants/question-theme-sort.dto.constants";

describe("Admin Find Question-Themes Query DTO Shape", () => {
  let validDto: {
    "sort-by"?: string;
    "sort-order"?: string;
    "limit": number;
    "status"?: string;
    "is-fully-translated"?: string;
  };

  beforeEach(() => {
    validDto = {
      "sort-order": "asc",
      "limit": LIMIT_DEFAULT,
    };
  });

  it("should pass validation when a valid dto is provided.", () => {
    expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(validDto)).not.toThrow();
  });

  it("should strip an unknown key when present.", () => {
    const dtoWithExtraKey = { ...validDto, extra: 1 };

    expect(ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithExtraKey)).not.toHaveProperty("extra");
  });

  describe("sort-by", () => {
    it.each<(typeof ADMIN_QUESTION_THEME_SORTABLE_FIELDS)[number]>(ADMIN_QUESTION_THEME_SORTABLE_FIELDS)("should pass validation when sort-by is '%s'.", sortBy => {
      const dto = { ...validDto, "sort-by": sortBy };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dto)).not.toThrow();
    });

    it("should throw zod error when sort-by is invalid.", () => {
      const dtoWithInvalidSortBy = { ...validDto, "sort-by": "invalid" };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithInvalidSortBy)).toThrow(ZodError);
    });

    it("should throw zod error when sort-by is 'cognitiveDifficulty' which is not a question-theme field.", () => {
      const dtoWithInvalidField = { ...validDto, "sort-by": "cognitiveDifficulty" };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithInvalidField)).toThrow(ZodError);
    });

    it("should use default value 'slug' when sort-by is not provided.", () => {
      const dtoWithoutSortBy = { "sort-order": "asc" };

      const result = ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithoutSortBy);

      expect(result["sort-by"]).toBe("slug");
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.shape["sort-by"].meta();
      const expectedMetadata = { description: QUESTION_THEME_SORT_BY_DESCRIPTION, example: QUESTION_THEME_SORT_BY_DEFAULT };

      expect(metadata).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("sort-order", () => {
    it.each<(typeof SORT_ORDERS)[number]>(SORT_ORDERS)("should pass validation when sort-order is '%s'.", sortOrder => {
      const dto = { ...validDto, "sort-order": sortOrder };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dto)).not.toThrow();
    });

    it("should throw zod error when sort-order is invalid.", () => {
      const dtoWithInvalidSortOrder = { ...validDto, "sort-order": "invalid" };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithInvalidSortOrder)).toThrow(ZodError);
    });

    it("should use default value 'asc' when sort-order is not provided.", () => {
      const dtoWithoutSortOrder = { "sort-by": "slug" };

      const result = ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithoutSortOrder);

      expect(result["sort-order"]).toBe("asc");
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.shape["sort-order"].meta();
      const expectedMetadata = { description: QUESTION_THEME_SORT_ORDER_DESCRIPTION, example: QUESTION_THEME_SORT_ORDER_DEFAULT };

      expect(metadata).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("limit", () => {
    it.each<number>([LIMIT_MINIMUM, LIMIT_DEFAULT, 100])("should pass validation when limit is %d.", limit => {
      const dto = { ...validDto, limit };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dto)).not.toThrow();
    });

    it.each<unknown>([-1, 1.5, "string", "", " ".repeat(3)])("should throw zod error when limit is '%s'.", limit => {
      const dtoWithInvalidLimit = { ...validDto, limit };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithInvalidLimit)).toThrow(ZodError);
    });

    it("should use default value 50 when limit is not provided.", () => {
      const dtoWithoutLimit = { "sort-by": "slug" };

      const result = ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithoutLimit);

      expect(result.limit).toBe(LIMIT_DEFAULT);
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.shape.limit.meta();
      const expectedMetadata = { description: LIMIT_DESCRIPTION, example: LIMIT_DEFAULT };

      expect(metadata).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("status", () => {
    it.each<(typeof QUESTION_THEME_STATUSES)[number]>(QUESTION_THEME_STATUSES)("should pass validation when status is '%s'.", status => {
      const dto = { ...validDto, status };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dto)).not.toThrow();
    });

    it("should throw zod error when status is invalid.", () => {
      const dtoWithInvalidStatus = { ...validDto, status: "invalid" };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithInvalidStatus)).toThrow(ZodError);
    });

    it("should pass validation when status is not provided.", () => {
      const { status: _status, ...dtoWithoutStatus } = validDto;

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithoutStatus)).not.toThrow();
    });

    it("should have correct description when accessing the description.", () => {
      expect(ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.shape.status.unwrap().description).toBe("Question Theme's status");
    });

    it("should have correct metadata when accessing the metadata.", () => {
      const metadata = ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.shape.status.unwrap().meta();
      const expectedMetadata = { description: "Question Theme's status", example: QUESTION_THEME_STATUSES[0] };

      expect(metadata).toStrictEqual<Record<string, unknown>>(expectedMetadata);
    });
  });

  describe("is-fully-translated", () => {
    it.each<string>(["true", "false"])("should pass validation when is-fully-translated is '%s'.", isFullyTranslated => {
      const dto = { ...validDto, "is-fully-translated": isFullyTranslated };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dto)).not.toThrow();
    });

    it("should parse is-fully-translated to a boolean when value is a valid boolean string.", () => {
      const dto = { ...validDto, "is-fully-translated": "false" };

      const result = ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dto);

      expect(result["is-fully-translated"]).toBeFalsy();
    });

    it("should throw zod error when is-fully-translated is invalid.", () => {
      const dtoWithInvalidValue = { ...validDto, "is-fully-translated": "maybe" };

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithInvalidValue)).toThrow(ZodError);
    });

    it("should pass validation when is-fully-translated is not provided.", () => {
      const dtoWithoutIsFullyTranslated: Record<string, unknown> = { ...validDto };
      delete dtoWithoutIsFullyTranslated["is-fully-translated"];

      expect(() => ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse(dtoWithoutIsFullyTranslated)).not.toThrow();
    });
  });

  it("should use both defaults when no fields are provided.", () => {
    const result = ADMIN_FIND_QUESTION_THEMES_QUERY_DTO.parse({});

    expect(result).toStrictEqual({ "sort-by": "slug", "sort-order": "asc", "limit": LIMIT_DEFAULT });
  });
});

